svg.script:
(function () {
  // Real gz lives in LFS (jsDelivr/raw serve only the LFS pointer file).
  var SOURCES = [
    'https://media.githubusercontent.com/media/retrograde-sdk/mcs/main/Gaius-26.2.html.gz',
    'https://api.github.com/repos/retrograde-sdk/mcs/git/blobs/bab0df544c0f2c0e7ed02afda983893a06eca519a8d8a97bef0769a0362331a6'
  ];
  var DB_NAME = 'gaius-launcher', STORE = 'html', KEY = 'Gaius-26.2', META = 'Gaius-26.2.meta', CACHE = 'gaius-launcher-v1';
  var DELAYS = [0, 5000, 15000, 45000, 45000];
  var attempt = 0;

  // --- tier 1: IndexedDB ---
  function idb() {
    return new Promise(function (resolve, reject) {
      var req = indexedDB.open(DB_NAME, 1);
      req.onupgradeneeded = function () { req.result.createObjectStore(STORE); };
      req.onsuccess = function () { resolve(req.result); };
      req.onerror = function () { reject(req.error || new Error('idb open failed')); };
      req.onblocked = function () { reject(new Error('idb blocked')); };
    });
  }
  function idbGet(key) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);
        tx.onsuccess = function () { resolve(tx.result || null); };
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }
  function idbPut(key, value) {
    return idb().then(function (db) {
      return new Promise(function (resolve, reject) {
        var tx = db.transaction(STORE, 'readwrite').objectStore(STORE).put(value, key);
        tx.onsuccess = function () { resolve(); };
        tx.onerror = function () { reject(tx.error); };
      });
    });
  }

  // --- tier 2: Cache API (used when IndexedDB is unavailable, e.g. blocked origins) ---
  function cacheGet() {
    return caches.open(CACHE).then(function (c) { return c.match('gaius:html'); });
  }
  function cachePut(html) {
    return caches.open(CACHE).then(function (c) {
      return c.put('gaius:html', new Response(html, { headers: { 'content-type': 'text/html' } }));
    });
  }

  // --- download (gz is only served by LFS media; API blob endpoint is the fallback) ---
  function viaFetch(url) {
    return fetch(url, { cache: 'force-cache' }).then(function (res) {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      return res.blob();
    });
  }
  function viaXhr(url) {
    return new Promise(function (resolve, reject) {
      var x = new XMLHttpRequest();
      x.open('GET', url);
      x.responseType = 'arraybuffer';
      x.timeout = 120000;
      x.onload = function () {
        if (x.status >= 200 && x.status < 300 && x.response) resolve(new Blob([x.response], { type: 'application/gzip' }));
        else reject(new Error('HTTP ' + x.status));
      };
      x.onerror = function () { reject(new Error('network')); };
      x.ontimeout = function () { reject(new Error('timeout')); };
      x.send();
    });
  }
  async function download() {
    for (var i = 0; i < SOURCES.length; i++) {
      try { return await viaFetch(SOURCES[i]); } catch (e) {}
      try { return await viaXhr(SOURCES[i]); } catch (e) {}
    }
    throw new Error('all sources failed');
  }
  // Freshness probe: published size (null when offline). LFS media returns the gz size.
  function remoteSize() {
    return fetch(SOURCES[0], { method: 'HEAD', cache: 'no-store' })
      .then(function (r) { return +(r.headers.get('content-length') || 0) || null; })
      .catch(function () { return null; });
  }

  function decompress(gzBlob) {
    return new Response(gzBlob.stream().pipeThrough(new DecompressionStream('gzip'))).text();
  }

  function boot(html) {
    document.open('text/html');
    document.write(html);
    document.close();
  }

  async function go() {
    // 1) Browser storage first: instant, offline-capable, no re-download.
    try {
      var cached = await idbGet(KEY).catch(function () { return null; });
      if (!cached) cached = await cacheGet().catch(function () { return null; });
      if (cached) {
        var meta = await idbGet(META).catch(function () { return null; });
        var remote = await remoteSize();
        if (!remote || !meta || !meta.size || remote === meta.size) { boot(await cached.text()); return; }
        // stale — refresh below
      }
    } catch (e) { /* fall through to network path */ }

    // 2) First run / refresh: download, decompress, persist in the browser, run.
    try {
      var gz = await download();
      var text = await decompress(gz);
      idbPut(KEY, new Blob([text], { type: 'text/html' })).catch(function () {});
      idbPut(META, { size: gz.size, at: Date.now() }).catch(function () {});
      cachePut(text).catch(function () {});
      boot(text);
    } catch (e) {
      if (++attempt < DELAYS.length) setTimeout(go, DELAYS[attempt]);
    }
  }

  go();
})();
